DECLARE
  l_savepoint_name         VARCHAR2(30) := 'SP_TEST_HEADCOUNT';
  l_failure_count          PLS_INTEGER := 0;

  l_min_dept_id            NUMBER;
  l_dept_with_rows         NUMBER;
  l_dept_without_rows      NUMBER;
  l_expected_count         NUMBER;
  l_actual_count           NUMBER;
  l_no_match_count         NUMBER;
  l_expected_no_match      NUMBER;
  l_expected_null          NUMBER;
  l_actual_null            NUMBER;

  PROCEDURE report_check(
    p_check_name IN VARCHAR2,
    p_expected   IN NUMBER,
    p_actual     IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_check_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_check_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
      l_failure_count := l_failure_count + 1;
    END IF;
  END report_check;
BEGIN
  SAVEPOINT sp_test_headcount;

  -- Find a non-NULL department_id that has at least one employee.
  BEGIN
    SELECT MIN(department_id)
      INTO l_min_dept_id
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_min_dept_id := NULL;
  END;

  -- Check 1: a department_id that should match at least one row.
  IF l_min_dept_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: existing department_id check expected a non-NULL department_id with employees, actual=no suitable row found'
    );
    l_failure_count := l_failure_count + 1;
  ELSE
    l_dept_with_rows := l_min_dept_id;

    SELECT COUNT(*)
      INTO l_expected_count
      FROM employees
     WHERE department_id = l_dept_with_rows;

    l_actual_count := harness_app.headcount(l_dept_with_rows);

    report_check(
      p_check_name => 'existing department_id count',
      p_expected   => l_expected_count,
      p_actual     => l_actual_count
    );
  END IF;

  -- Check 2: a non-NULL department_id that should match no row.
  IF l_min_dept_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL: no-match department_id check expected a non-NULL department_id with no employees, actual=no suitable row found'
    );
    l_failure_count := l_failure_count + 1;
  ELSE
    l_dept_without_rows := l_min_dept_id - 1;

    SELECT COUNT(*)
      INTO l_no_match_count
      FROM employees
     WHERE department_id = l_dept_without_rows;

    IF l_no_match_count <> 0 THEN
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: no-match department_id check expected a department_id with no employees, actual=department_id ' ||
        l_dept_without_rows || ' matched ' || l_no_match_count || ' row(s)'
      );
      l_failure_count := l_failure_count + 1;
    ELSE
      l_expected_no_match := 0;
      l_actual_count := harness_app.headcount(l_dept_without_rows);

      report_check(
        p_check_name => 'no-match department_id count',
        p_expected   => l_expected_no_match,
        p_actual     => l_actual_count
      );
    END IF;
  END IF;

  -- Check 3: NULL argument. The function compares department_id = p_department_id,
  -- so NULL should match no rows.
  SELECT COUNT(*)
    INTO l_expected_null
    FROM employees
   WHERE department_id = NULL;

  l_actual_null := harness_app.headcount(NULL);

  report_check(
    p_check_name => 'NULL department_id count',
    p_expected   => l_expected_null,
    p_actual     => l_actual_null
  );

  ROLLBACK TO sp_test_headcount;

  IF l_failure_count <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'headcount test block failed: ' || l_failure_count || ' check(s) failed'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO sp_test_headcount;
    RAISE;
END;
```

The block checks three cases:

1. A non-NULL `department_id` that has at least one employee. It computes the expected count with a separate `SELECT COUNT(*)` query and compares it with the result of calling `harness_app.headcount`.
2. A non-NULL `department_id` that should match no employee row. It uses `MIN(department_id) - 1` as a candidate, confirms with `COUNT(*)` that no row matches, then compares the function result with expected `0`. If no suitable no-match value can be found, the check prints `FAIL` and counts as a failure.
3. A `NULL` argument. The expected value is computed using the same comparison the function uses, `department_id = NULL`, which matches no rows, so the expected result is the no-match result, not a count of rows where `department_id IS NULL`.

I have not run this block.

